import JSZip from 'jszip';

function generateFavicons(sourceImage: HTMLImageElement): Promise<Map<string, Blob>> {
  const sizes = [16, 32, 48, 64, 128, 256];
  const favicons = new Map<string, Blob>();

  for (const size of sizes) {
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(sourceImage, 0, 0, size, size);

    const blob = await new Promise<Blob>((resolve) => {
      canvas.toBlob((b) => resolve(b!), 'image/png');
    });

    favicons.set(`favicon-${size}x${size}.png`, blob);
  }

  return favicons;
}

async function downloadAsZip(favicons: Map<string, Blob>): Promise<void> {
  const zip = new JSZip();

  for (const [filename, blob] of favicons) {
    zip.file(filename, blob);
  }

  const content = await zip.generateAsync({ type: 'blob' });
  // ダウンロード処理
}
```

