【FFmpeg.wasm使用】
既存のimage-to-gif.tsxのFFmpeg実装を参考にする。

【技術実装】
```typescript
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { fetchFile } from '@ffmpeg/util';

async function convertVideoToGif(
  videoFile: File,
  options: {
    fps: number;
    width: number;
    height: number;
    quality: number;
    startTime: number;
    endTime: number;
  }
): Promise<Blob> {
  const ffmpeg = new FFmpeg();
  await ffmpeg.load();

  await ffmpeg.writeFile('input.mp4', await fetchFile(videoFile));

  await ffmpeg.exec([
    '-i', 'input.mp4',
    '-ss', options.startTime.toString(),
    '-to', options.endTime.toString(),
    '-vf', `fps=${options.fps},scale=${options.width}:${options.height}:flags=lanczos,split[s0][s1];[s0]palettegen[p];[s1][p]paletteuse`,
    '-loop', '0',
    'output.gif'
  ]);

  const data = await ffmpeg.readFile('output.gif');
  return new Blob([data], { type: 'image/gif' });
}
```

