【技術実装（HTTP/HTTPSのみ）】
```typescript
export const checkHttpPorts = createServerFn({ method: 'GET' })
  .handler(async ({ data: url }) => {
    const ports = [80, 443, 8080, 8443];
    const results: Array<{ port: number; status: 'open' | 'closed'; protocol: string }> = [];

    for (const port of ports) {
      try {
        const protocol = [443, 8443].includes(port) ? 'https' : 'http';
        const targetUrl = `${protocol}://${url}:${port}`;

        const response = await fetch(targetUrl, {
          method: 'HEAD',
          signal: AbortSignal.timeout(5000)
        });

        results.push({
          port,
          status: response.ok || response.status < 500 ? 'open' : 'closed',
          protocol
        });
      } catch {
        results.push({ port, status: 'closed', protocol: '' });
      }
    }

    return results;
  });
```

